"use client";

import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from "@/components/ui/select";
import { Eye, Mail, Phone, PhoneCallIcon } from "lucide-react";
import Link from "next/link";
import { useEffect, useMemo, useState } from "react";

export default function QueriesPage() {
  const [data, setData] = useState([]);
  const [search, setSearch] = useState("");
  const [department, setDepartment] = useState("all");
  const [sort, setSort] = useState("latest");

  useEffect(() => {
    fetch("/api/queries")
      .then((res) => res.json())
      .then(setData);
  }, []);

  // 🔍 Filter + Search + Sort logic
  const filteredData = useMemo(() => {
    let result = [...data];

    // Search
    if (search) {
      result = result.filter((q) =>
        [q.name, q.email, q.phone_number]
          .join(" ")
          .toLowerCase()
          .includes(search.toLowerCase())
      );
    }

    // Filter by department
    if (department !== "all") {
      result = result.filter((q) => q.department === department);
    }

    // Sort
    result.sort((a, b) => {
      const dateA = new Date(a.date);
      const dateB = new Date(b.date);
      return sort === "latest" ? dateB - dateA : dateA - dateB;
    });

    return result;
  }, [data, search, department, sort]);

  // Get unique departments
  const departments = [
    ...new Set(
      data
        .map((q) => q.department)
        .filter((dep) => dep && dep.trim() !== "")
    ),
  ];

  return (
    <div className="p-6 space-y-6">

      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold">Patient Queries</h1>
        <p className="text-sm text-muted-foreground">
          Manage and review patient enquiries
        </p>
      </div>

      {/* Controls */}
      <Card className="p-4 flex flex-col md:flex-row gap-4 md:items-center md:justify-between">

        {/* Search */}
        <Input
          placeholder="Search by name, email, phone..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="md:max-w-sm"
        />

        <div className="flex gap-3 flex-wrap">

          {/* Filter */}
          <Select onValueChange={setDepartment} defaultValue="all">
            <SelectTrigger className="w-[180px]">
              <SelectValue placeholder="Department" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Departments</SelectItem>
              {departments.map((dep, i) => (
                <SelectItem key={i} value={dep}>
                  {dep}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          {/* Sort */}
          <Select onValueChange={setSort} defaultValue="latest">
            <SelectTrigger className="w-[150px]">
              <SelectValue placeholder="Sort" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="latest">Latest</SelectItem>
              <SelectItem value="oldest">Oldest</SelectItem>
            </SelectContent>
          </Select>

        </div>
      </Card>

      {/* List */}
      <div className="grid gap-4">
        {filteredData.length > 0 ? (
          filteredData.map((query, index) => (
            <Card
              key={index}
              className="p-5 rounded-2xl shadow-sm hover:shadow-md transition border"
            >
              <div className="grid md:grid-cols-2 gap-3 text-sm">

                <p><span className="font-semibold">Name:</span> {query.name}</p>
                <p><span className="font-semibold">Phone:</span> {query.phone_number}</p>
                <p><span className="font-semibold">Email:</span> {query.email}</p>
                <p><span className="font-semibold">City:</span> {query.city}</p>
                <p><span className="font-semibold">Department:</span> {query.department}</p>
                <p><span className="font-semibold">Date:</span> {new Date(query.date).toLocaleString()}</p>

              </div>
              <div className="flex gap-2 flex-wrap">

    <Link
      href={`tel:${query.phone_number}`}
      className="px-3 py-1.5 text-xs rounded-lg bg-indigo-900 border hover:bg-muted flex gap-2"
    >
      <Phone size={18} className="text-white"/> 
      <span className="text-white">Call</span>
    </Link>

    <Link
      href={`mailto:${query.email}`}
      className="px-3 py-1.5 text-xs rounded-lg bg-teal-700 border hover:bg-muted flex gap-2"
    >
      <Mail size={18} className="text-white"/>
      <span className="text-white">Email</span>
    </Link>

    <Select
  defaultValue={query.status || "new"}
  onValueChange={(value) => {
    console.log("Update status:", query.id, value);

    // 👉 later replace with API call
    // fetch(`/api/queries/${query.id}`, {
    //   method: "PATCH",
    //   body: JSON.stringify({ status: value }),
    // });
  }}
>
  <SelectTrigger className="w-[140px] h-8 text-xs">
    <SelectValue placeholder="Status" />
  </SelectTrigger>

  <SelectContent>
    <SelectItem value="new">🆕 New</SelectItem>
    <SelectItem value="contacted">📞 Contacted</SelectItem>
    <SelectItem value="closed">✅ Closed</SelectItem>
  </SelectContent>
</Select>
  </div>
            </Card>
          ))
        ) : (
          <p className="text-center text-muted-foreground py-10">
            No queries found
          </p>
        )}
      </div>

    </div>
  );
}